import{_ as t,o as a,c as o,a5 as s}from"./chunks/framework.BwlBv862.js";const p=JSON.parse('{"title":"Use TikTools","description":"","frontmatter":{"title":"Use TikTools","docId":"user.overview","translationKey":"user.overview","locale":"en","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"72ce37218d4f3341fccd306bd0b1b4039ec6e1fd3dcfeb16f9096f43576c861d","translationRevision":"72ce37218d4f3341fccd306bd0b1b4039ec6e1fd3dcfeb16f9096f43576c861d","order":0},"headers":[],"relativePath":"en/user/index.md","filePath":"en/user/index.md","lastUpdated":1794591482000}'),i={name:"en/user/index.md"};function n(r,e,l,d,c,u){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="use-tiktools" tabindex="-1">Use TikTools <a class="header-anchor" href="#use-tiktools" aria-label="Permalink to &quot;Use TikTools {#use-tiktools}&quot;">​</a></h1><p>TikTools connects a Windows or Linux desktop to a TikTok LIVE, displays its events, keeps viewer points and runs rules on your computer. The desktop interface and the optional headless host share the same Rust core. A Cloud account is separate from the TikTok connection.</p><h2 id="choose-your-first-task" tabindex="-1">Choose your first task <a class="header-anchor" href="#choose-your-first-task" aria-label="Permalink to &quot;Choose your first task {#choose-your-first-task}&quot;">​</a></h2><ol><li>Check the <a href="./requirements.html">requirements</a> and <a href="./installation.html">install a released binary</a>. You do not need Rust, Cargo or Bun to use the desktop release.</li><li><a href="./first-live.html">Connect to a LIVE</a>, starting without a TikTok cookie when the room permits guest access.</li><li>Use <strong>Live feed</strong> to inspect events. <strong>Points</strong> keeps viewer totals; <strong>Analytics</strong> shows statistics. <strong>Automations</strong> connects triggers to configured actions.</li><li>Install optional integrations from <strong>Plugins</strong>. External plugin packages are distributed separately from the application.</li><li>Use <strong>Overlays</strong> to prepare a Browser Source for OBS. The gateway integration is required for live widget delivery.</li></ol><h2 id="available-and-experimental-features" tabindex="-1">Available and experimental features <a class="header-anchor" href="#available-and-experimental-features" aria-label="Permalink to &quot;Available and experimental features {#available-and-experimental-features}&quot;">​</a></h2><p>The main navigation exposes Live feed, Points, Analytics, Connections, Automations, Plugins, Overlays and Settings. Rankings and competitions have a native engine and a direct route, but their management page is still hidden from normal navigation. Do not assume every prototype described in an older design document is a released feature.</p><p>Cloud plugin changes and reviewed Variables use explicit section controls. Automations currently compares against a local reference copy; that button does not publish profiles to Cloud. Collaboration transports and some installer handoffs remain experimental. A disabled control usually indicates a missing host capability or an unmet prerequisite.</p><h2 id="when-something-fails" tabindex="-1">When something fails <a class="header-anchor" href="#when-something-fails" aria-label="Permalink to &quot;When something fails {#when-something-fails}&quot;">​</a></h2><p>Open <strong>Diagnostics</strong>, keep the error source and request identifier, and record the installed app version. Avoid including cookies, invitation tokens or private variable values. Start with the error recovery in each guide, then use the support guides. The interactive demo uses fictional data and cannot establish whether your TikTok account, OBS or network works.</p><p>For source development, use the separate <a href="./../developer/">developer documentation</a>.</p>',10)])])}const f=t(i,[["render",n]]);export{p as __pageData,f as default};
